/* @lc app=leetcode id=3981 lang=kotlin */ class Solution { fun interleaveCharacters(word1: String, word2: String, target: String): Int = 1_000_000_007L.let { M -> target.fold(Array(word1.length + 1) { p -> LongArray(word2.length + 1) { q -> if (p == 0 && q == 0) 1L else 0L } }) { dp, c -> dp.runningFold(LongArray(word2.length + 1)) { acc, row -> LongArray(word2.length + 1) { (acc[it] + row[it]) % M } }.let { s1 -> Array(word1.length + 1) { p -> dp[p].runningFold(0L) { a, b -> (a + b) % M }.let { s2 -> LongArray(word2.length + 1) { q -> ((if (p > 0 && word1[p - 1] == c) s1[p][q] else 0L) + (if (q > 0 && word2[q - 1] == c) s2[q] else 0L)) % M } } } } }.let { dp -> (1..word1.length).sumOf { p -> (1..word2.length).sumOf { q -> dp[p][q] } } % M }.toInt() } }